const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Load the local index.html
  const filePath = path.resolve('index.html');
  const htmlContent = fs.readFileSync(filePath, 'utf8');

  // Set content and wait for load
  await page.setContent(htmlContent, { waitUntil: 'load' });

  // Inject axe-core
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Run axe
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, nodes: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, help: v.help, nodes: v.nodes.map(n => n.target) }))
  }, null, 2));

  process.exit(wcag.length > 0 ? 1 : 0);
})();

