     width: 100%;
     max-width: 400px;
 }

 h1 {
     font-size: 1.5rem;
     margin-bottom: 1.5rem;
     text-align: center;
 }

 .form-field {
     margin-bottom: 1.5rem;
 }

 fieldset {
     border: none;
     padding: 0;
     margin: 0;
 }

 legend {
     font-weight: 600;
     margin-bottom: 1rem;
     display: block;
 }

 .required {
     color: var(--color-error);
     margin-left: 0.25rem;
 }

 .radio-group {
     display: flex;
     flex-direction: column;
     gap: 0.75rem;
 }

 .radio-option {
     display: flex;
     align-items: center;
     position: relative;
 }

 /* Custom Radio Styling */
 input[type="radio"] {
     appearance: none;
     background-color: transparent;
     margin: 0;
     font: inherit;
     color: currentColor;
     width: 1.25em;
     height: 1.25em;
     border: 2px solid var(--color-text-muted);
     border-radius: 50%;
     transform: translateY(-0.075em);
     display: grid;
     place-content: center;
     cursor: pointer;
     transition: border-color 0.2s ease-in-out;
 }

 input[type="radio"]::before {
     content: "";
     width: 0.65em;
     height: 0.65em;
     border-radius: 50%;
     transform: scale(0);
     transition: 120ms transform ease-in-out;
     box-shadow: inset 1em 1em var(--color-primary);
     background-color: CanvasText; /* Forced Colors support */
 }

 input[type="radio"]:checked {
     border-color: var(--color-primary);
 }

 input[type="radio"]:checked::before {
     transform: scale(1);
 }

 input[type="radio"]:focus-visible {
     outline: 2px solid var(--color-focus);
     outline-offset: 4px;
 }

 /* Label styling */
 label {
     margin-left: 0.75rem;
     cursor: pointer;
     font-size: 1rem;
 }

 .submit-button {
     background-color: var(--color-primary);
     color: #000;
     border: none;
     padding: 0.75rem 1.5rem;
     border-radius: 4px;
     font-size: 1rem;
     font-weight: 600;
     width: 100%;
     cursor: pointer;
     transition: background-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
 }

 .submit-button:hover, .submit-button:focus {
     background-color: var(--color-secondary);
 }

 .submit-button:focus-visible {
     outline: 2px solid var(--color-focus);
     outline-offset: 4px;
 }

 .error-message {
     color: var(--color-error);
     font-size: 0.875rem;
     margin-top: 0.5rem;
 }

 .status-message {
     margin-top: 1.5rem;
     text-align: center;
     padding: 0.75rem;
     border-radius: 4px;
     background-color: rgba(3, 218, 198, 0.1);
     border: 1px solid var(--color-secondary);
     color: var(--color-secondary);
 }

 /* Forced Colors support */
 @media (forced-colors: active) {
     input[type="radio"] {
         border-color: ButtonBorder;
     }
     input[type="radio"]:checked {
         border-color: Highlight;
     }
     input[type="radio"]:focus-visible {
         outline: 2px solid Highlight;
     }
     .submit-button {
         border: 1px solid ButtonBorder;
     }
 }
     </style>
 </head>
 <body>
     <main>
         <section class="container">
             <h1>Notification Settings</h1>
             <form id="notification-form" novalidate>
                 <div class="form-field">
                     <fieldset aria-describedby="error-message">
                         <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
                         <div class="radio-group">
                             <div class="radio-option">
                                 <input type="radio" id="pref-email" name="notification-preference" value="email" required>
                                 <label for="pref-email">Email</label>
                             </div>
                             <div class="radio-option">
                                 <input type="radio" id="pref-sms" name="notification-preference" value="sms" required>
                                 <label for="pref-sms">SMS</label>
                             </div>
                             <div class="radio-option">
                                 <input type="radio" id="pref-push" name="notification-preference" value="push" required>
                                 <label for="pref-push">Push Notifications</label>
                             </div>
                         </div>
                         <p id="error-message" class="error-message" hidden aria-live="polite"></p>
                     </fieldset>
                 </div>
                 <button type="submit" class="submit-button">Save Preferences</button>
             </form>
             <p id="status-message" class="status-message" hidden aria-live="polite"></p>
         </section>
     </main>
     <script>
 document.addEventListener('DOMContentLoaded', () => {
     const form = document.getElementById('notification-form');
     const statusMessage = document.getElementById('status-message');
     const errorMessage = document.getElementById('error-message');

     form.addEventListener('submit', (event) => {
         event.preventDefault();

         // Clear previous messages
         statusMessage.hidden = true;
         errorMessage.textContent = '';
         errorMessage.hidden = true;

         const formData = new FormData(form);
         const preference = formData.get('notification-preference');

         if (!preference) {
             errorMessage.textContent = 'Error: Please select a notification preference.';
             errorMessage.hidden = false;

             // Focus the first radio button if validation fails
             const firstRadio = form.querySelector('input[type="radio"]');
             if (firstRadio) firstRadio.focus();
             return;
         }

         // Simulate successful submission
         statusMessage.textContent = `Preferences saved! You will receive notifications via ${preference.toUpperCase()}.`;
         statusMessage.hidden = false;

         // Optionally, reset form
         // form.reset();
     });
 });
     </script>
 </body>
 </html>

')
